```js
function lastSubstantiveCommitActor(repoInfo, headSha, machineLogin) {
    // Sticky-park RESET probe v3 (dmtools-agents#681, live fa#1213
    // 2026-10-03): the newest NON-machine commit on the branch's
    // FIRST-PARENT chain. The silent-update bot merge / an agent auto-save
    // can land between the owner's retrigger push and the next SM tick —
    // the machine commit becomes the head and a HEAD-only actor probe
    // reads 'machine', holding the park forever (the head never moves
    // again once the branch is up to date). Bot merges of main are never
    // the retrigger: walk back past them and test the last substantive
    // commit's actor + date instead.
    // Machine = the 'sm-silent-update' committer identity (silentUpdateBranch
    // stamps it on its merge commits — its noreply email maps to no GitHub
    // login) or the deployment's machineAuthor login on author OR committer
    // (agent-leg pushes land as that login — headCommitActor v2).
    // FIRST-PARENT only: the plain ancestor list interleaves main's
    // history, and a fresh human commit on MAIN (merged in BY the bot)
    // must not read as this branch's retrigger.
    // Returns {sha, login, date} of the first non-machine commit, or null
    // when the walk fails / sees only machine commits (fail closed: the
    // caller keeps the park — same contract as headCommitActor).
    try {
        var res = cli_execute_command({
            command: 'gh api "repos/' + repoInfo.owner + '/' + repoInfo.repo +
                     '/commits?sha=' + headSha + '&per_page=30"'
        });
        var parsed = mcpParse((res || {}).output || (res || {}).stdout || res);
        var list = Array.isArray(parsed) ? parsed : [];
        var bySha = {};
        list.forEach(function (c) { if (c && c.sha) bySha[c.sha] = c; });
        var machineLoginL = String(machineLogin || '').toLowerCase();
        var cur = headSha;
        for (var i = 0; i < 30 && bySha[cur]; i++) {
            var c = bySha[cur];
            var commit = c.commit || {};
            var committerName = String((commit.committer || {}).name || '');
            var authorLogin = String((c.author || {}).login || '').toLowerCase();
            var committerLogin = String((c.committer || {}).login || '').toLowerCase();
            var isMachine = committerName === 'sm-silent-update' ||
                (!!machineLoginL &&
                 (authorLogin === machineLoginL || committerLogin === machineLoginL));
            if (!isMachine) {
                return {
                    sha: c.sha,
                    login: authorLogin || committerLogin,
                    date: String((commit.committer || {}).date || '')
                };
            }
            var parents = c.parents || [];
            if (!parents.length || !parents[0] || !parents[0].sha) break;
            cur = parents[0].sha;
        }
        return null;
    } catch (e) {
        console.warn('  ⚠️  substantive-commit probe failed: ' + (e.message || e));
        return null;
    }
