/**
 * Agent docs coverage test — fails when a tracked agent config has no
 * up-to-date generated documentation.
 *
 * For every git-tracked root *.json agent config this checks that
 * docs/agents/generated/<name>.md exists and documents:
 *   - every referenced JS action (preJSAction / preCliJSAction /
 *     postCliJSAction / postJSAction / timerJSAction) by file basename;
 *   - every customParams key declared in the JSON;
 *   - every customParams path used by the referenced JS action sources.
 *
 * If this test fails after your change, regenerate the docs:
 *   node js/agentDocGenerator.js   (run from the parent repo root)
 * and commit the updated docs/agents/generated/*.md files.
 */

var AGENT_JSON_PATTERN = /^[a-zA-Z0-9_]+\.json$/;
var ACTION_PARAMS = ['preJSAction', 'preCliJSAction', 'postCliJSAction', 'postJSAction', 'timerJSAction'];
var EXCLUDED = {
    'sm.json': true,
    'sm_merge.json': true,
    'versions.json': true // pack-version registry, not an agent config
};

function listTrackedAgentConfigs() {
    var output = cli_execute_command({ command: 'git ls-files "*.json"' });
    return (output || '').split('\n').filter(function(f) {
        if (!f || !f.trim()) return false;
        var path = f.trim();
        if (path.indexOf('/') !== -1) return false; // root configs only
        var name = path.replace(/^.*\//, '');
        if (EXCLUDED[name]) return false;
        if (name.indexOf('run_') === 0) return false;
        if (name.indexOf('_lock') !== -1) return false;
        return AGENT_JSON_PATTERN.test(name);
    }).map(function(f) { return f.trim(); });
}

function readText(path) {
    try {
        return file_read({ path: path });
    } catch (e) {
        return null;
    }
}

function extractCustomParamsPaths(src) {
    var found = {};
    var re1 = /customParams\.([a-zA-Z_$][\w$]*(?:\.[a-zA-Z_$][\w$]*)*)/g;
    var re2 = /customParams\[['"]([\w.]+)['"]\]/g;
    var match;
    while ((match = re1.exec(src)) !== null) found[match[1]] = true;
    while ((match = re2.exec(src)) !== null) found[match[1]] = true;
    return Object.keys(found);
}

function actionBasename(actionPath) {
    return String(actionPath).replace(/^.*\//, '');
}

suite('agentDocsCoverage', function() {

/**
 * Human-readable doc for an agent. Location by strict naming convention:
 * docs/agents/<configName>.md (configName = JSON file name without .json).
 * metadata.descriptionPath may point to the same file explicitly, but the
 * convention path is always checked as a fallback.
 * Returns { ref, content } or null when no human doc exists.
 */
function humanDocPath(fileName, params) {
    var metadata = (params && params.metadata) || {};
    var base = fileName.replace(/\.json$/, '.md');
    var candidates = [];
    if (metadata.descriptionPath) candidates.push(metadata.descriptionPath);
    candidates.push(path.join(AGENTS_DIR, 'docs', 'agents', base));
    for (var i = 0; i < candidates.length; i++) {
        var p = candidates[i];
        try {
            var content = fs.readFileSync(resolveReadPath(p), 'utf8');
            if (content && content.trim()) {
                return { ref: canonicalRef(path.join(AGENTS_DIR, 'docs', 'agents', base)), content: content };
            }
        } catch (e) {
            // try next candidate
        }
    }
    return null;
}

function renderAgentDoc(fileName, config) {
    var params = config.params || {};
    var metadata = params.metadata || {};
    var customParams = params.customParams || {};
    var outputSchemas = params.outputSchemas || null;

    var jobClass = config.name || '—';
    var contextId = metadata.contextId || '—';

    // Humanized config name as the page title: "story_acceptance_criteria" →
    // "Story acceptance criteria". The job class and file name stay in the
    // Attributes table — a title like `Teammate (story_acceptance_criteria.json)`
    // renders as an unreadable headline in HTML.
    var displayName = fileName.replace(/\.json$/, '').replace(/_/g, ' ')
        .replace(/\b\w/g, function(c) { return c.toUpperCase(); });

    var lines = [];
    lines.push('# ' + displayName);
    lines.push('');

    // Human-readable description lives in docs/agents/<name>.md (strict naming
    // convention, see humanDocPath). It is embedded verbatim so the generated
    // reference stays self-contained and HTML-renderable.
    var human = humanDocPath(fileName, params);
    if (human) {
        var humanBody = human.content.trim()
            .replace(/^#\s+.*\n/, '')       // drop the human doc's own title
            .trim();
        lines.push(humanBody);
        lines.push('');
        lines.push('_Human doc: [`' + human.ref + '`](' + human.ref + ')_');
        lines.push('');
    }

