    var human = humanDocPath(fileName, params);
    if (human) {
        var humanBody = human.content.trim()
            .replace(/^#\s+.*\n/, '')       // drop the human doc's own title
            .trim();
        lines.push(humanBody);
        lines.push('');
        lines.push('_Human doc: [`' + human.ref + '`](' + human.ref + ')_');
        lines.push('');
    }

