        // machine itself (sm-silent-update committer, machine actor
        // login, STALE date — neither human nor fresh). The sha change
        // is the verdict.
        onCliExecute: (function () {
            var base = vfCli({ parkedAt: '2026-10-01T00:00:00Z' });
