}

function extractCustomParamsPaths(src) {
    var found = {};
    var re1 = /customParams\.([a-zA-Z_$][\w$]*(?:\.[a-zA-Z_$][\w$]*)*)/g;
    var re2 = /customParams\[['"]([\w.]+)['"]\]/g;
    var match;
    while ((match = re1.exec(src)) !== null) found[match[1]] = true;
    while ((match = re2.exec(src)) !== null) found[match[1]] = true;
